-- PT119-S2-Q6. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT119-S2-Q6$batch03$ AND q.stimulus=$batch03$University budget committee: Athletes experience fewer injuries on artificial-turf athletic fields than on natural-grass fields. Additionally, natural-grass fields are more expensive to maintain than fields made of artificial turf. Nevertheless, this committee recommends replacing the university’s current artificial-turf field with a natural-grass field.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent discrepancy in the committee's position?$batch03$ AND q.correct_choice=$batch03$B$batch03$) THEN RAISE EXCEPTION 'Question changed: PT119-S2-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT119-S2-Q6$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S2-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT119-S2-Q6$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Artificial turf causes fewer injuries and costs less to maintain than grass.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$The committee recommends replacing the turf with grass?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The committee's own evidence favors turf on both counts. To resolve this, find something that outweighs those advantages. The injury figure counts injuries, not how bad they are. If turf injuries are worse and cost more, fewer injuries might still be the worse deal.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a reason grass is better despite fewer injuries and lower maintenance on turf.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT119-S2-Q6$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$The current turf has needed a lot of maintenance, but we already know grass costs more to maintain. This does not outweigh that.$batch03$), ($batch03$B$batch03$, $batch03$Turf injuries are fewer, but each one heals more slowly and needs more expensive therapy. That cost could outweigh the cheaper maintenance and make turf the more expensive field overall, which is the kind of reason a budget committee acts on.$batch03$), ($batch03$C$batch03$, $batch03$Whether spectators can tell the difference does not affect injuries or cost.$batch03$), ($batch03$D$batch03$, $batch03$This lists different maintenance tasks, but we already know grass is more expensive to maintain overall.$batch03$), ($batch03$E$batch03$, $batch03$This is a *budget* committee, so player preference is not the kind of reason that drives its recommendation. And nothing says this university's athletes have played mostly on grass, so we do not even know the preference applies to them.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT119-S2-Q6$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
